46:/// Keep one namespace from a binary config schema, including the `$defs` it
47:/// references. The rest of the monolith stays out. The retained bytes are the
48:/// binary's own schema nodes.
49:pub fn filter_namespace(document: &Value, namespace: &str) -> Result<Value> {
50:    let section = document
51:        .pointer(&format!("/properties/{namespace}"))
52:        .with_context(|| format!("binary schema has no namespace '{namespace}'"))?
53:        .clone();
54:    let mut defs = Map::new();
55:    let mut seen = HashSet::new();
56:    collect_defs(&section, document, &mut defs, &mut seen);
57:    let mut filtered = section;
58:    if !defs.is_empty() {
59:        if let Value::Object(map) = &mut filtered {
60:            map.insert("$defs".to_string(), Value::Object(defs));
61:        }
62:    }
63:    Ok(filtered)
64:}
65:
66:fn collect_defs(
67:    node: &Value,
68:    document: &Value,
69:    defs: &mut Map<String, Value>,
70:    seen: &mut HashSet<String>,
71:) {
72:    match node {
73:        Value::Object(map) => {
74:            if let Some(Value::String(reference)) = map.get("$ref")
75:                && let Some(name) = reference.strip_prefix("#/$defs/")
76:                && seen.insert(name.to_string())
77:                && let Some(def) = document.pointer(&format!("/$defs/{name}"))
78:            {
79:                defs.insert(name.to_string(), def.clone());
80:                collect_defs(def, document, defs, seen);
81:            }
82:            for value in map.values() {
83:                collect_defs(value, document, defs, seen);
84:            }
85:        }
86:        Value::Array(items) => {
87:            for item in items {
88:                collect_defs(item, document, defs, seen);
89:            }
90:        }
91:        _ => {}
92:    }
93:}
