95:/// Command words from a binary help listing, limited to the words that address
96:/// a config path. `help` is not a method.
97:pub fn filter_command_words(help: &str, allowed: &[&str]) -> Vec<String> {
98:    let allowed: BTreeSet<&str> = allowed.iter().copied().collect();
99:    let mut words = Vec::new();
100:    let mut in_commands = false;
101:    for line in help.lines() {
102:        if line.trim() == "Commands:" {
103:            in_commands = true;
104:            continue;
105:        }
106:        if !in_commands {
107:            continue;
108:        }
109:        if line.trim().is_empty() {
110:            continue;
111:        }
112:        if !line.starts_with("  ") {
113:            break;
114:        }
115:        let Some(name) = line.split_whitespace().next() else {
116:            continue;
117:        };
118:        if allowed.contains(name) {
119:            words.push(name.to_string());
120:        }
121:    }
122:    words
123:}
