161:fn ensure_capability(schema: &mut PluginSchema, id: &str, description: &str) {
162:    schema.capabilities.entry(id.to_string()).or_insert_with(|| {
163:        CapabilityDecl {
164:            id: id.to_string(),
165:            description: description.to_string(),
166:        }
167:    });
168:}
