170:fn method_decl(
171:    command: &str,
172:    section: &Value,
173:    side_effect: SideEffect,
174:    idempotent: bool,
175:    capability: &str,
176:) -> MethodDecl {
177:    let category = if matches!(side_effect, SideEffect::Read) {
178:        "obs"
179:    } else {
180:        "mut"
181:    };
182:    let args = if command == "set" {
183:        serde_json::json!({
184:            "type": "object",
185:            "additionalProperties": true,
186:            "properties": {
187:                "help": { "type": "boolean" },
188:                "value": section
189:            }
190:        })
191:    } else if command == "patch" {
192:        serde_json::json!({
193:            "type": "object",
194:            "additionalProperties": true,
195:            "properties": {
196:                "help": { "type": "boolean" },
197:                "operations": { "type": "array" }
198:            }
199:        })
200:    } else {
201:        serde_json::json!({
202:            "type": "object",
203:            "additionalProperties": true,
204:            "properties": {
205:                "help": { "type": "boolean" }
206:            }
207:        })
208:    };
209:    MethodDecl {
210:        name: command.to_string(),
211:        args: to_simd(&args),
212:        returns: Some(to_simd(&serde_json::json!({
213:            "type": "object",
214:            "additionalProperties": false,
215:            "required": ["stdout", "stderr", "exit"],
216:            "properties": {
217:                "stdout": { "type": "string" },
218:                "stderr": { "type": "string" },
219:                "exit": { "type": "integer" }
220:            }
221:        }))),
222:        side_effect,
223:        idempotent,
224:        required_capability: Some(capability.to_string()),
